def mad(numbers: List[float], mean: float) -> float:
    # calculate the mean deviation around a mean
    num_deviation = 0
    for x in numbers:
        deviation = abs(x - mean)
        num_deviation += deviation

    # divide by number of deviations plus one (because mean calculated
    # divided by number of observations)
    return (num_deviation / (len(numbers) + 1))


