def nested_parens_recur(paren_string: str) -> List[int]:
    if not paren_string:
        return []

    if ')' not in paren_string:
        return [(len(paren_string))]

    paren_levels = []

    stack_of_indices = [-1]
    next_index = -1

    for i in range(len(paren_string)):
        if not paren_levels:
            next_index = paren_string.find('(', next_index + 1)
        if next_index:
            paren_levels.append(i)
            next_index = paren_string.find('(', next_index + 1)
        elif paren_string[i] != '(':
            index_to_top_index = {i: paren_levels[-2]} if len(paren_levels) > 1 else {}
            stack_of_indices.insert(0, max(index_to_top_index))
    paren_levels.append(i)

    return paren_levels + nested_parens_recur(paren_string[next_index:])

