def root_mean_square(numbers: List[float]) -> float:
    """ Calculate Root Mean Square (RMS) around mean in dataset. RMS is
    the square root of the mean value of the square of a dataset.
    >>> root_mean_square([1, 1, 1])
    1.0
    >>> root_mean_square([-1, 1])
    1.0
    >>> root_mean_square([2, 4, 6, 8])
    5.0
    """
    return float(
        (
            sum(
                [
                    pow(abs(x - mean(numbers)), 2)
                    for x in numbers
                ]
            )
        )
        / len(numbers)
    ) ** 0.5


