    """ Input to this function is a group of nested parentheses represented by spaces,
    E.g. (()()) has three levels of nesting.

    >>> get_max_level('(()())')
    2
    """
    result = 0
    i = 0
    count = 0
    while i < len(paren_string):
        c = paren_string[i]
        if c == '(':
            count += 1
        elif c == ')':
