def parse_nested_parens_corrected(paren_string: str) -> List[int]:
    """Same functionality as `parse_nested_parens`,
    except that output list should be in order given group order in paren_string."""

    def stack_of_parens(paren_string):
        output = []
        stack = []
        counter = 0
        i = 0
        while i < len(paren_string):
            char = paren_string[i]
            if char == '(':
                counter += 1
                if not stack:
                    output.append((counter, i))
                stack.append(i)
            elif char == ')':
                counter -= 1
                if counter == 0:
                    output.append((counter, len(paren_string)))
                else:
                    i_index = output[-1][1]
                    parent_i, parent_j = stack.pop(), i_index + 1
                    while parent_j < parent_i:
                        output[-1][1] = parent_i
                        parent_j += 1
                    stack.append(parent_i)
                    if parent_i < len(paren_string):
                        output.append((counter, parent_i))

            i += 1

        return output

    return stack_of_parens(paren_string)

